import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects registration of a static tool whose inputSchema cannot be compiled, naming the tool and leaving it unregistered', () => {
    const registry = new ToolRegistry();
    let thrownMessage = '';

    try {
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {type: 'object', properties: {id: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      );
    } catch (error) {
      thrownMessage = error instanceof Error ? error.message : String(error);
    }

    expect({namesTool: thrownMessage.includes('broken_lookup'), registered: registry.has('broken_lookup')}).toEqual({
      namesTool: true,
      registered: false,
    });
  });

  it('validates a function-valued tool against the schema returned for the current call', async () => {
    const registry = new ToolRegistry();
    let required = 'first';
    registry.register(
      () => ({
        name: 'shifting',
        description: 'Schema changes between calls',
        inputSchema: {type: 'object', properties: {[required]: {type: 'string'}}, required: [required]},
      }),
      async () => 'ok'
    );

    const beforeChange = await registry.execute('shifting', {first: 'a'});
    required = 'second';
    const beforeChange = await registry.execute('shifting', {first: 'a'});
    required = 'second';
    const afterChange = await registry.execute('shifting', {first: 'a'});

    expect({
      beforeChange: beforeChange.result,
      afterChangeNamesSecond: afterChange.result.includes('second'),
    }).toEqual({beforeChange: 'ok', afterChangeNamesSecond: true});
  });

  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'lookup',
        description: 'Requires a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        received.push(input);
        return 'ok';
      }
    );

    await registry.execute('lookup', {location: 'Berlin', extra: 7});

    expect(received).toEqual([{location: 'Berlin', extra: 7}]);
  });
});
12:- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
13:- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
14:- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an unlisted extra property to the executor unchanged, exactly once](../../src/orchestration/tools/registry.test.ts#L49)).
15:- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.
19:- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94), [validated by: rejects registration of a static tool whose inputSchema cannot be compiled, naming the tool and leaving it unregistered](../../src/orchestration/tools/registry.test.ts#L4)).
21:- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates a function-valued tool against the schema returned for the current call](../../src/orchestration/tools/registry.test.ts#L27)).
25:- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
